// spec: .qa/e2e/specs/devices.md (2.1)
// seed: tests/seed.user.spec.ts
// НИКОГДА не нажимать «הסרה», «שמירה», не переключать роли.
import { test, expect, type Page, type Route } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(240_000);

// «משהו השתבש — לא הצלחנו לטעון את המידע. בדקו את החיבור ונסו שוב.»: заголовок + текст
const ERROR_TITLE = 'משהו השתבש';
const ERROR = 'לא הצלחנו לטעון את המידע. בדקו את החיבור ונסו שוב.';
// Чтения устройств (GET /rest/v1/devices: список и поиск своего телефона). Изменения (PATCH) не трогаем.
const isDevicesGet = (u: URL) => u.pathname.endsWith('/rest/v1/devices');

const rowsOf = (page: Page) => page.getByRole('button', { name: /, (מחובר|לא מחובר)$/ }).filter({ visible: true });
async function snapshot(page: Page): Promise<string[]> {
  await expect(rowsOf(page).first()).toBeVisible();
  return (await rowsOf(page).evaluateAll((els) => els.map((e) => (e as HTMLElement).innerText)))
    .map((t) => t.replace(/[\u200e\u200f\u2066-\u2069]/g, '').replace(/\s+/g, ' ').trim())
    .sort();
}

test.describe('«מכשירים» — ошибка загрузки и «נסו שוב»', () => {
  test('После ошибки загрузки и «נסו שוב» своя строка снова «הטלפון הזה», без баннера «לא מחובר», экран = обычной загрузке #1c852837 @iphone @prod-safe', async ({ page }) => {
    // 1. Обычная загрузка — эталон
    await page.goto('/account/devices');
    const reference = await snapshot(page);
    const own = reference.find((r) => r.includes('הטלפון הזה'));
    expect(own, 'сессия user.json не привязана к устройству — обновить qa-login').toBeTruthy();
    await expect(page.getByText('הטלפון הזה עוד לא מחובר לחשבון').filter({ visible: true }), 'сессия user.json не привязана к устройству — обновить qa-login').toHaveCount(0);
    const ownRole = /(מכשיר ראשי|מכשיר נוסף)/.exec(own!)![1];

    // 2–5. Три сбоя подряд: 500, обрыв сети (замена авиарежима; только веб — перехват запроса), 500
    const failures: Array<(r: Route) => Promise<void>> = [
      (r) => r.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"QA-AUTO error"}' }),
      (r) => r.abort('internetdisconnected'),
      (r) => r.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"QA-AUTO error"}' }),
    ];
    for (const [i, fail] of failures.entries()) {
      const handler = async (r: Route) => (r.request().method() === 'GET' ? fail(r) : r.continue());
      await page.route(isDevicesGet, handler);
      await page.reload();
      await expect(page.getByText(ERROR).filter({ visible: true }), `сбой ${i + 1}: сообщение об ошибке`).toBeVisible({ timeout: 90_000 });
      // Приложение само повторяет запрос: при 500 ошибка через ~5–10 с, при обрыве сети — через ~50 с (наблюдение 12.10).
      await expect(page.getByRole('heading', { name: ERROR_TITLE }).filter({ visible: true })).toBeVisible();
      const retry = page.getByRole('button', { name: 'נסו שוב' }).filter({ visible: true });
      await expect(retry).toBeVisible();

      await page.unroute(isDevicesGet, handler);
      await retry.click();

      const after = await snapshot(page);
      expect(after, `после «נסו שוב» ${i + 1}: экран = обычной загрузке`).toEqual(reference);
      const ownAfter = after.find((r) => r.includes('הטלפון הזה'));
      expect(ownAfter).toContain(ownRole);
      await expect(page.getByText('הטלפון הזה עוד לא מחובר לחשבון').filter({ visible: true })).toHaveCount(0);
      await expect(page.getByText('ניהול כל המכשירים עם סיסמה').filter({ visible: true })).toHaveCount(0);
      await expect(page.getByText(ERROR).filter({ visible: true })).toHaveCount(0);
      await expect(page.getByRole('heading', { name: ERROR_TITLE }).filter({ visible: true })).toHaveCount(0);
    }

    // 6. Своя строка → окно роли → «הסרת הטלפון מהחשבון» → «זה הטלפון שבידכם.» → «ביטול» → «סגירה»
    await rowsOf(page).filter({ hasText: 'הטלפון הזה' }).click();
    const dialog = page.getByRole('dialog').filter({ visible: true });
    await expect(dialog.getByText('מה הטלפון הזה עושה?')).toBeVisible();
    await dialog.getByRole('button', { name: 'הסרת הטלפון מהחשבון' }).click();
    await expect(dialog.getByText(/זה הטלפון שבידכם\./)).toBeVisible();
    await dialog.getByRole('button', { name: 'ביטול', exact: true }).click(); // НЕ «הסרה»
    await expect(dialog.getByText('מה הטלפון הזה עושה?')).toBeVisible();
    // «סגירה» — затемнённый фон над окном: нажимаем в его верхний угол, не в центр (в центре — переключатели роли). НЕ «שמירה».
    await dialog.getByRole('button', { name: 'סגירה' }).click({ position: { x: 8, y: 8 } });
    await expect(page.getByRole('dialog').filter({ visible: true })).toHaveCount(0);
    await expect(page).toHaveURL(/\/account\/devices/);
    expect(await snapshot(page)).toEqual(reference);
  });
});
